(* [comment removed for export] *)
Definition elemsW (E : list Z) : list (Z * Z) := map (fun a => (a, a + 48)) E.
Definition insW (lo hi Fa : Z) (E : list Z) : list (Z * Z) := (lo, hi) :: (Fa, Fa + 48) :: elemsW E.

Lemma outside_elemsW : forall E u, outside (elemsW E) u <-> (forall a, a ∈ E -> ~ (a <= u < a + 48)).
Proof.
  intros E u. induction E as [|y E IH]; cbn.
  - split; [intros _ a IN; rewrite elem_of_nil in IN; destruct IN| intros; exact I].
  - rewrite IH. split.
    + intros [H1 H2] a IN. rewrite elem_of_cons in IN. destruct IN as [<-|IN]; [exact H1| exact (H2 a IN)].
    + intros H. split; [apply H; rewrite elem_of_cons; left; reflexivity|]. intros a IN. apply H. rewrite elem_of_cons. right; exact IN.
Qed.

Lemma munch_insW_of_frame : forall lo hi Fa E lo' hi' m m',
  munch [(lo', hi')] m m' -> lo <= lo' -> hi' <= hi -> munch (insW lo hi Fa E) m m'.
Proof. intros lo hi Fa E lo' hi' m m' MU H1 H2. eapply munch_weaken; [| exact MU]. intros u [K _]. cbn. split; [lia| exact I]. Qed.

Lemma munch_insW_of_frame2 : forall lo hi Fa E lo' hi' r m m',
  munch [(lo', hi'); (r, r + 8)] m m' -> lo <= lo' -> hi' <= hi -> lo <= r -> r + 8 <= hi -> munch (insW lo hi Fa E) m m'.
Proof. intros lo hi Fa E lo' hi' r m m' MU H1 H2 H3 H4. eapply munch_weaken; [| exact MU]. intros u [K _]. cbn. split; [lia|]. split; [lia| exact I]. Qed.

(* [comment removed for export] *)
Lemma munch_insW_of_ibW : forall lo hi Fa E X lo' hi' m m',
  munch (ibW lo' hi' X) m m' -> lo <= lo' -> hi' <= hi ->
  (forall x, x ∈ X -> x = Fa \/ x - 16 ∈ E) -> munch (insW lo hi Fa E) m m'.
Proof.
  intros lo hi Fa E X lo' hi' m m' MU H1 H2 SUB. eapply munch_weaken; [| exact MU]. intros u (K & R & Q). cbn. split; [lia|].
  rewrite outside_nodesW. rewrite outside_elemsW in Q. intros x IN. destruct (SUB x IN) as [->|INE]; [lia|].
  pose proof (Q _ INE). lia.
Qed.

Lemma inside_insW_elem : forall lo hi Fa E a u n, a ∈ E -> a <= u -> u + n <= a + 48 -> inside (insW lo hi Fa E) u n.
Proof.
  intros lo hi Fa E a u n IN H1 H2. cbn. right. right.
  induction E as [|y E IH]; [rewrite elem_of_nil in IN; destruct IN|]. cbn.
  rewrite elem_of_cons in IN. destruct IN as [<-|IN]; [left; lia| right; exact (IH IN)].
Qed.

Lemma disjoint_insW : forall lo hi Fa E u n,
  (u + n <= lo \/ hi <= u) -> (u + n <= Fa \/ Fa + 48 <= u) -> (forall a, a ∈ E -> u + n <= a \/ a + 48 <= u) ->
  disjoint_from (insW lo hi Fa E) u n.
Proof.
  intros lo hi Fa E u n H1 H2 H3. cbn. split; [exact H1|]. split; [exact H2|].
  induction E as [|y E IH]; [exact I|]. cbn. split.
  - apply H3. rewrite elem_of_cons. left; reflexivity.
  - apply IH. intros a IN. apply H3. rewrite elem_of_cons. right; exact IN.
Qed.

Lemma inside_insW_frame : forall lo hi Fa E u n, lo <= u -> u + n <= hi -> inside (insW lo hi Fa E) u n.
Proof. intros. cbn. left. lia. Qed.
Lemma inside_insW_hdr : forall lo hi Fa E u n, Fa <= u -> u + n <= Fa + 48 -> inside (insW lo hi Fa E) u n.
Proof. intros. cbn. right. left. lia. Qed.

(* [comment removed for export] *)
Lemma inside_insW_elem2 : forall lo hi Fa E a, a ∈ E ->
  inside (insW lo hi Fa E) (a + Z.of_nat 0) (Z.of_nat 8) /\ inside (insW lo hi Fa E) (a + Z.of_nat 8) (Z.of_nat 8).
Proof. intros lo hi Fa E a IN. split; apply (inside_insW_elem _ _ _ _ a _ _ IN); lia. Qed.
Lemma inside_insW_root2 : forall lo hi Fa E,
  inside (insW lo hi Fa E) (Fa + 32 + Z.of_nat 0) (Z.of_nat 8) /\ inside (insW lo hi Fa E) (Fa + 32 + Z.of_nat 8) (Z.of_nat 8).
Proof. intros lo hi Fa E. split; apply inside_insW_hdr; lia. Qed.

(* [comment removed for export] *)
Ltac prove_inside_insW :=
  first [ apply inside_insW_frame; lia
        | apply inside_insW_hdr; lia
        | match goal with
          | H : ?a ∈ ?E |- inside (insW _ _ _ ?E) _ _ => apply (inside_insW_elem _ _ _ _ a _ _ H); lia
          end
        | match goal with
          | H : ?a ∈ ?L0 |- inside (insW _ _ _ (_ :: ?L0)) _ _ => apply (inside_insW_elem _ _ _ _ a); [rewrite elem_of_cons; right; exact H| lia| lia]
          end
        | match goal with
          | |- inside (insW _ _ _ (?a :: _)) _ _ => apply (inside_insW_elem _ _ _ _ a); [rewrite elem_of_cons; left; reflexivity| lia| lia]
          end ].

Ltac footprint_after_store segs m a bs ::=
  repeat match goal with
  | MU : munch ?Wq ?mq m |- _ =>
      first [ apply (munch_write Wq mq m a bs) in MU; [ | lia | simpl_sizes; slia | first [assumption | prove_inside_ibW | simpl_sizes; prove_inside_insW] ]
            | fail 100 "store outside the declared footprint:" a ]
  | WMo : wmono segs ?mq m |- _ => apply (wmono_write segs mq m (wa a) bs) in WMo
  | STq : stk segs m ?loq ?hiq |- _ =>
      first [ apply (stk_write segs m loq hiq a bs) in STq; [ | lia | simpl_sizes; slia ]
            | fail 100 "cannot transport stk hypothesis" STq ]
  end.

(* [comment removed for export] *)
Ltac transport_after_call_ins segs m m' MU WM :=
  let W := lazymatch type of MU with munch ?W _ _ => W end in
  repeat match goal with
  | H : bytes_at segs m ?A2 ?bs2 |- _ =>
      first [ apply (bytes_at_transport segs W m m' A2 bs2) in H; [ | exact MU | cbn [disjoint_from]; simpl_sizes; slia ]
            | lazymatch W with ibW ?lo ?hi ?X =>
                apply (bytes_at_ibW lo hi X m m' A2 bs2) in H; [ | exact MU | simpl_sizes; lia | ibW_disj_nodes ] end
            | idtac "note: dropping hypothesis (not provably disjoint from callee footprint):" H; clear H ]
  | H : wr_at segs m ?A2 ?n2 |- _ => apply (wr_at_transport segs m m' A2 n2) in H; [ | exact WM ]
  | H : rw_cells segs m ?A2 ?cs2 |- _ =>
      first [ apply (rw_cells_transport segs W m m' A2 cs2) in H; [ | exact MU | exact WM | cbn [disjoint_from]; simpl_sizes; slia ]
            | lazymatch W with ibW ?lo ?hi ?X =>
                apply (rw_cells_ibW lo hi X m m' A2 cs2) in H; [ | exact MU | exact WM | simpl_sizes; lia | ibW_disj_nodes ] end
            | idtac "note: dropping hypothesis (not provably disjoint from callee footprint):" H; clear H ]
  | H : stk segs m ?loq ?hiq |- _ =>
      first [ apply (stk_transport_disjoint segs W m m' loq hiq) in H; [ | exact MU | exact WM | cbn [disjoint_from]; slia ]
            | clear H ]
  | H : munch ?Wq ?mq m |- _ =>
      first [ apply (munch_trans Wq mq m m') in H; [ | exact MU ]
            | apply (munch_trans Wq mq m m') in H; [ | eapply munch_ibW_mono; [exact MU | lia | lia] ]
            | apply (munch_trans Wq mq m m') in H; [ | eapply munch_ibW_of_frame; [exact MU | lia | lia] ]
            | apply (munch_trans Wq mq m m') in H; [ | eapply munch_insW_of_frame; [exact MU | lia | lia] ]
            | apply (munch_trans Wq mq m m') in H; [ | eapply munch_insW_of_frame2; [exact MU | lia | lia | lia | lia] ]
            | apply (munch_trans Wq mq m m') in H; [ | eapply munch_insW_of_ibW; [exact MU | lia | lia | assumption] ]
            | apply (munch_trans Wq mq m m') in H; [ | eapply (munch_weaken W Wq m m'); [ unfold sub_fp; cbn [outside]; intros; slia | exact MU ] ]
            | fail 100 "callee footprint not inside caller footprint" ]
  | H : wmono segs ?mq m |- _ => apply (wmono_trans segs mq m m') in H; [ | exact WM ]
  end.

Ltac post_call_ins segs m :=
  let ms' := fresh "ms'" in let PO := fresh "POST" in
  intros ms' PO;
  (let h := head_of ltac:(type of PO) in try unfold h in PO);
  rewrite ?unsigned_lit in PO by lia; rewrite ?Z.add_0_r in PO;
  destruct_exs PO;
  let E := fresh "E" in let MUc := fresh "MUc" in let WMc := fresh "WMc" in let MIc := fresh "MI" in
  destruct PO as [E [MUc [WMc PO]]];
  first [ destruct PO as [MIc PO] | rename PO into MIc ];
  subst ms';
  lazymatch type of MUc with
  | munch _ m ?m' =>
      transport_after_call_ins segs m m' MUc WMc;
      clear MUc WMc;
      try match goal with H : mem_inv segs m |- _ => clear H end;
      try clear m
  end;
  try destruct_ands PO;
  try (lazymatch goal with
  | |- evt _ _ (MS _ _ (ret_pc (Z_to_bv 64 ?n)) _ _ _ _) =>
      replace (ret_pc (Z_to_bv 64 n)) with (Z_to_bv 64 n) by (symmetry; apply ret_pc_even; [ lia | reflexivity ])
  end).

Tactic Notation "call_ins" uconstr(SPEC) :=
  lazymatch goal with
  | |- evt ?segs _ (MS _ _ _ _ _ ?m _) => eapply evt_cut; [ eapply SPEC | post_call_ins segs m ]
  end.

