Section LSRdef.
  Context {HCEIL : HeapCeil}.

Definition LAcc (m : mem) (ls : LS) : Prop :=
  forall a n, ls !! a = Some n -> a mod 8 = 0 /\ aapp a 16 /\ accessible m a 16.

Definition ALSR (m : mem) (ls : LS) : Prop := ALSCells m ls /\ ls_sep ls /\ LAcc m ls.

Lemma ALSR_node : forall m ls a n, ALSR m ls -> ls !! a = Some n ->
  lnode_wf n /\ (AIMG_TOP <= a /\ a + 16 <= aceil /\ a mod 8 = 0) /\ rw_cells asegs m a (LNodeCells n).
Proof.
  intros m ls a n (LC & SEP & LA) L. split; [exact (ALSCells_wf _ _ _ _ LC L)|]. split; [| exact (ALSCells_lookup _ _ _ _ LC L)].
  destruct (LA a n L) as (AL & AP & _). pose proof (aapp_bounds _ _ AP ltac:(lia)) as (B1 & B2 & _). repeat split; assumption.
Qed.

Lemma ALSR_rd : forall m ls a n k, ALSR m ls -> ls !! a = Some n -> (k = 0 \/ k = 8) ->
  ov_read_bytes asegs m (Z_to_bv 64 (Z.shiftr (a + k) 3 + 2147450880)) 1 = Some [b8 0].
Proof. intros m ls a n k (_ & _ & LA) L K. destruct (LA a n L) as (AL & _ & AC). exact (lacc_rd m a k AC AL K). Qed.

Lemma LAcc_transport : forall W m m' ls, LAcc m ls -> munch W m m' -> Forall awin W -> LAcc m' ls.
Proof.
  intros W m m' ls LA MU FW a n L. destruct (LA a n L) as (AL & AP & AC). split; [exact AL|]. split; [exact AP|].
  eapply accessible_transport_awin; eauto.
Qed.
