(* [comment removed for export] *)
Lemma AFieldsC_assemble : forall m Fa S L ns ls em e d S' L' ns' ls',
  AFieldsC m Fa S L ns ls em -> new_elt_ok Fa em e d ->
  (forall m1, ANSCells m1 ns' -> ALSCells m1 ls' -> AEMCells m1 (<[e := d]> em) ->
   rb_ok Fa S' ns' -> sorted key_lt (key_of (<[e := d]> em)) S' -> dl_ok (Fa + 32) L' ls' ->
   sl_rel S' L' -> (forall a, a ∈ L' <-> a = e \/ a ∈ L) ->
   AEMShad m1 (<[e := d]> em) -> AHdrA m1 Fa ->
   AFieldsC m1 Fa S' L' ns' ls' (<[e := d]> em)).
Proof.
  intros m Fa S L ns ls em e d S' L' ns' ls' FC NEW m1 NC LC EC OK SO DL SL LEQ ESH1 HA1.
  pose proof FC as (_ & _ & _ & _ & _ & _ & _ & LE & EOK & _ & _ & _).
  destruct (new_elt_fresh _ _ _ _ _ _ _ _ _ FC NEW) as (NONE & _ & _ & _ & _ & _ & _ & _ & EOK' & HS').
  split; [exact NC|]. split; [exact LC|]. split; [exact EC|]. split; [exact OK|]. split; [exact SO|]. split; [exact DL|].
  split; [exact SL|]. split.
  { intros a. rewrite LEQ. destruct (Z.eq_dec a e) as [->|NE].
    - rewrite lookup_insert_eq. split; [intros _; eexists; reflexivity| intros _; left; reflexivity].
    - rewrite lookup_insert_ne by (intros E; apply NE; symmetry; exact E). rewrite <- LE.
      split; [intros [E|IN]; [exfalso; exact (NE E)| exact IN]| intros IN; right; exact IN]. }
  split; [exact EOK'|]. split; [exact ESH1|]. split; [exact HA1| exact HS'].
Qed.

(* [comment removed for export] *)
Lemma LNodeCells_of_junk : forall m a junk,
  rw_cells asegs m a [CB 16 junk] -> exists ln, lnode_wf ln /\ rw_cells asegs m a (LNodeCells ln).
Proof.
  intros m a junk H.
  pose proof H as [[WF _] _]. cbn in WF. destruct WF as [L _].
  set (b0 := firstn 8 junk). set (b1 := skipn 8 junk).
  assert (L0 : length b0 = 8%nat) by (subst b0; rewrite length_firstn; lia).
  assert (L1 : length b1 = 8%nat) by (subst b1; rewrite length_skipn; lia).
  assert (EJ : junk = b0 ++ b1) by (subst b0 b1; symmetry; apply firstn_skipn).
  pose proof (bytes_le_to_Z_bound b0) as B0. rewrite L0 in B0. pose proof (bytes_le_to_Z_bound b1) as B1. rewrite L1 in B1.
  cbn in B0, B1.
  exists (mkLNode (bytes_le_to_Z b0) (bytes_le_to_Z b1)).
  split. { unfold lnode_wf; cbn [l_next l_prev]. lia. }
  eapply rw_cells_recells; [exact H| | |].
  - cbn. repeat split; exact I.
  - unfold LNodeCells, wz. cbn [cells_bytes cbytes l_next l_prev].
    rewrite (le8_of_bytes b0 L0), (le8_of_bytes b1 L1). rewrite EJ. rewrite !app_nil_r. reflexivity.
  - reflexivity.
Qed.

Definition insel_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (Fa e : Z) (d : elt) (L : list Z) (em : gmap Z elt) (lo shi : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' S' L' ns' ls',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (insW lo (bv_unsigned sp) Fa (e :: L)) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ AFieldsC m' Fa S' L' ns' ls' (<[e := d]> em)
    /\ (e + 16) ∈ S' /\ e ∈ L'
    /\ ACONST m' /\ stack0 m' lo shi.

Definition insel_stmt : Prop := forall (Fa e : Z) (d : elt) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt)
    (lo shi : Z) (junk : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  AFieldsC m Fa S L ns ls em ->
  rw_cells asegs m e [CB 48 junk] -> rw_cells asegs m (e + 48) (ValCells d) -> new_elt_ok Fa em e d ->
  stk asegs m lo (bv_unsigned sp) -> lo + INSEL_STACK <= bv_unsigned sp -> aceil <= lo ->       (* [comment removed for export] *)
  mem_inv asegs m ->
  (* [comment removed for export] *)
  bv_unsigned sp mod 16 = 0 -> ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
  addressable m e (esize d) -> shvis m (e + 16) (e + 48) ->
  evt asegs (insel_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc Fa e d L em lo shi m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz Fa) (wz e) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_FIELDS_INSERT_ELEMENT) fc None m (seg_rom asegs)).
Scheme kc__5 := Elimination for Corelib.Init.Logic.ex Sort Prop.

