(* [comment removed for export] *)
Lemma insW_awin : forall m Fa S L ns ls em e d lo hi,
  AFieldsC m Fa S L ns ls em -> new_elt_ok Fa em e d -> aceil <= lo -> Forall awin (insW lo hi Fa (e :: L)).
Proof.
  intros m Fa S L ns ls em e d lo hi FC NEW CE.
  pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE & EOK & ESH & HA & HS).
  pose proof NEW as (EP & EAL & EHI & WFd & EAP & EA8 & DJ & HSE). pose proof (esize_ge d) as EG.
  unfold insW. apply Forall_cons; [apply awin_stack; exact CE|].
  apply Forall_cons; [destruct HA as (AP & _); eapply awin_aapp; [exact AP| lia| lia]|].
  cbn [elemsW map]. apply Forall_cons; [eapply awin_aapp; [exact EAP| lia| lia]|].
  apply Forall_forall. intros iv IN. apply in_map_iff in IN. destruct IN as (x & <- & IN).
  apply (proj2 (list_elem_of_In _ _)) in IN. apply LE in IN. destruct IN as [dx Lx].
  pose proof (esize_ge dx). eapply awin_aapp; [exact (em_ok_aapp _ _ _ EOK Lx)| lia| lia].
Qed.


